          if (searchR && UK.in(t, searchR)) { UK.tap(s, p); askTextBox(s, { question: 'Search Marketplace', placeholder: 'Bike, sofa, phone…', value: q, max: 60 }, (v) => { if (v != null) { q = String(v).trim(); S.v = 0; } }); continue; }
