      if (on) { popT = s.time; parts = Array.from({ length: 8 }, (_, i) => ({ a: i / 8 * Math.PI * 2, t: s.time })); s.engine.vibrate?.(12); }
      if (p.message) s.send(p.message, on ? 1 : 0);
