          if (b.h >= 76 && TOOLS.length) { tools = []; TOOLS.forEach(([k, ic], i) => { const cx = tx + 10 + i * 34, y = b.y + 64; drawIco(ctx, ic, cx, y, 19, hint, { stroke: 2 }); tools.push({ k, x: cx - 16, y: y - 16, w: 32, h: 32 }); }); }
