          if (bw) { ctx.fillStyle = acc; UK.rr(ctx, b.x + b.w - 10 - bw, b.cy - 17, bw, 34, 17); ctx.fill(); UK.text(ctx, p.button, b.x + b.w - 10 - bw / 2, b.cy + 1, { size: 14, weight: 800, color: '#fff' }); }
