          if (j === i) { ctx.fillStyle = withAlpha(acc, 0.2); ctx.fillRect(b.x, y, b.w, G.rh); }
          UK.text(ctx, o.label, b.x + 16, y + G.rh / 2, { size: tsz, weight: j === i ? 800 : 600, color: j === i ? acc : txt, align: 'left' });
