  remove(kind, test) { const c = this.coll(kind); if (c) { for (const r of this.D.rows(c).filter(test)) this.D.remove(c, r.id); return; } const o = this.local(); o[kind] = o[kind].filter((r) => !test(r)); this.saveLocal(o); this.changed(kind); }
