  const bar = s.add({ name: '(loading bar)', ui: true, anchor: 'center', x: 0, y: 24, layer: L + 2, bar: { var: '__loading', max: 100, w: W - 60, h: 6, fill: '#6ea0ff', bg: 'rgba(255,255,255,0.15)', radius: 3, busy: true } });
