              if (p.tapMode === 'steps toward the tap') { const ox = w.x - e.x, oy = wy - (three ? e.z : e.y); if (Math.hypot(ox, oy) > T() * 0.4) { path = [Math.abs(ox) > Math.abs(oy) ? [Math.sign(ox), 0] : [0, Math.sign(oy)]]; goal = null; } }
