  params: [{ key: 'triggers', label: 'Triggers', type: 'triggers', default: [{ event: { type: 'tap' }, conditions: [], actions: [{ type: 'setVar', name: 'score', op: 'add', value: 1 }, { type: 'punch', what: 'scale', amount: 0.3, seconds: 0.4 }] }] }],
